const optionId = (label) => label.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "");
const finishOf = (label) => /metallic/i.test(label) ? "metallic" : /matt/i.test(label) ? "matte" : /gloss/i.test(label) ? "gloss" : /laid|ribbed|vellum/i.test(label) ? "ribbed" : void 0;
function tableOptionGroups(productId, t) {
	const group = (key, name, labels, order) => ({
		id: `grp-${productId}-${key}`,
		productId,
		name,
		inputType: "select",
		isRequired: true,
		sortOrder: order,
		values: labels.map((label, idx) => ({
			id: optionId(label),
			groupId: `grp-${productId}-${key}`,
			label,
			sortOrder: idx + 1,
			isActive: true,
			finishType: key === "a" ? finishOf(label) : void 0
		}))
	});
	return [group("a", t.rowName, t.rows, 1), group("b", t.colName, t.cols, 2)];
}
function tablePriceCells(productId, t) {
	const cells = [];
	t.prices?.forEach((row, r) => row.forEach((price, c) => {
		if (price == null) return;
		const a = optionId(t.rows[r]);
		const b = optionId(t.cols[c]);
		cells.push({
			id: `pm-${productId}-${a}-${b}`,
			productId,
			optionValueA: a,
			optionValueB: b,
			price,
			isActive: true
		});
	}));
	return cells;
}
