function makeProduct(p) {
	const table = PRICE_TABLES[p.id];
	const prices = (table.prices ?? []).flat().filter((x) => x != null);
	return {
		id: p.id,
		slug: p.slug,
		name: p.name,
		shortDescription: p.shortDescription,
		longDescription: p.longDescription,
		categoryId: p.categoryId,
		categoryName: CATEGORY_NAME[p.categoryId],
		basePrice: prices.length ? Math.min(...prices) : 0,
		isVariable: true,
		isFeatured: !!p.isFeatured,
		isHot: !!p.isHot,
		deliveryNote: p.deliveryNote,
		sizeNote: p.sizeNote,
		isActive: p.isActive ?? true,
		sortOrder: p.sortOrder,
		createdAt: CREATED_AT,
		images: p.images.map((imageUrl, i) => ({
			id: `img-${p.id}-${i + 1}`,
			productId: p.id,
			imageUrl,
			altText: p.imageAlt,
			sortOrder: i + 1,
			isPrimary: i === 0
		})),
		optionGroups: tableOptionGroups(p.id, table),
		specs: p.specs
	};
}
